import '../../features/intelligence/domain/intelligence_library.dart';
import 'portuguese_portugal_text.dart';

/// Brazilian Portuguese wording for the curated offline intelligence reference.
class PortugueseIntelligenceContent {
  PortugueseIntelligenceContent._();

  static const Map<String, Map<String, String>> _entries = {
    'url-http': {'title':'HTTP sem criptografia','signal':'Um endereço de site começa com http:// em vez de https://.','meaning':'A conexão não usa TLS para proteger os dados em trânsito. As informações trocadas podem ficar expostas ou ser alteradas na rede.','action':'Evite inserir senhas ou dados de pagamento. Acesse a organização usando um favorito confiável ou um endereço verificado de forma independente.','limit':'HTTPS protege a conexão; não comprova que o próprio site seja legítimo.'},
    'url-userinfo': {'title':'Informações de usuário enganosas na URL','signal':'Uma URL contém texto antes do símbolo @, por exemplo https://trusted.example@unknown.example/.','meaning':'Os navegadores interpretam o texto depois de @ como nome do host. O texto aparentemente confiável antes dele pode servir para distrair.','action':'Leia o nome real do host logo após @ e verifique o domínio registrável antes de visitar.','limit':'Informações de usuário em uma URL são incomuns, mas não comprovam, por si só, intenção maliciosa.'},
    'url-punycode': {'title':'Domínio internacionalizado / Punycode','signal':'Um nome de host contém um rótulo xn-- ou caracteres visualmente semelhantes.','meaning':'Nomes de domínio internacionalizados podem usar caracteres de diferentes sistemas de escrita que se parecem com letras latinas.','action':'Confira a grafia exata e o titular do domínio usando uma fonte confiável. Não confie apenas em um logotipo ou nome de exibição familiar.','limit':'Muitos sites legítimos usam nomes de domínio internacionalizados.'},
    'url-subdomains': {'title':'Cadeia profunda de subdomínios','signal':'Um nome de host contém vários rótulos, como login.account.example.invalid.','meaning':'O domínio registrado não é necessariamente a primeira palavra familiar no endereço. Invasores podem colocar nomes de marcas em subdomínios que controlam.','action':'Leia o nome do host da direita para a esquerda e identifique o domínio registrável. Verifique-o de forma independente.','limit':'Cadeias longas de subdomínios também têm usos legítimos.'},
    'message-urgency': {'title':'Urgência e pressão','signal':'Uma mensagem exige ação imediata, ameaça encerrar uma conta ou impõe um prazo artificial.','meaning':'A pressão pode desencorajar a verificação independente e levar o destinatário a agir sem pensar.','action':'Faça uma pausa. Entre em contato com a organização por um aplicativo, site ou telefone oficial já conhecido, e não pelos dados da mensagem.','limit':'Linguagem urgente também pode aparecer em comunicações legítimas; o contexto importa.'},
    'message-credentials': {'title':'Solicitação de credenciais ou OTP','signal':'Um remetente pede senha, OTP, código de recuperação ou aprovação de uma solicitação inesperada de login.','meaning':'Esses segredos ou aprovações podem dar acesso a uma conta ou autorizar uma transação.','action':'Nunca revele senhas ou OTPs. Recuse solicitações inesperadas de aprovação e contate o serviço pelo canal oficial.','limit':'Uma correspondência de palavras-chave identifica apenas um assunto; não determina quem enviou a mensagem nem sua intenção.'},
    'message-payment': {'title':'Pagamento ou reembolso inesperado','signal':'Uma mensagem solicita transferência, taxa de processamento, ação de reembolso ou pagamento para liberar um benefício.','meaning':'Instruções financeiras inesperadas podem ser usadas para desviar fundos ou coletar dados de pagamento.','action':'Verifique o beneficiário, o valor e o motivo por outro canal confiável antes de agir.','limit':'Linguagem sobre pagamentos também é comum em faturas e notificações legítimas de serviços.'},
    'qr-payment': {'title':'Solicitação de pagamento por QR','signal':'Um conteúdo QR usa um esquema de pagamento, como upi://pay.','meaning':'A leitura pode preparar um pagamento para um destinatário. Um código QR não autentica o beneficiário nem garante que o valor esteja correto.','action':'Confira o nome do beneficiário, o ID UPI e o valor no aplicativo de pagamento antes de autorizar. Cancele se algo estiver diferente.','limit':'Um conteúdo de pagamento não é fraudulento por natureza; verifique os detalhes da transação.'},
    'qr-action': {'title':'Código QR com link de ação','signal':'Um conteúdo QR inclui uma ação web, telefônica, de e-mail, SMS ou específica de aplicativo.','meaning':'O conteúdo pode abrir um destino ou preencher uma ação quando processado por outro aplicativo.','action':'Examine primeiro o conteúdo decodificado. Não abra links desconhecidos nem aprove ações preenchidas sem verificar.','limit':'O tipo de conteúdo, por si só, não determina se a origem é confiável.'},
    'account-mfa': {'title':'Aprovação inesperada de MFA','signal':'Você recebe uma solicitação de aprovação de login ou um código de uso único que não pediu.','meaning':'Alguém pode estar tentando entrar usando o identificador e a senha da sua conta, ou o código pode ter sido gerado por engano.','action':'Recuse a solicitação, não compartilhe o código, altere a senha pelo serviço oficial se necessário e revise as sessões ativas.','limit':'Uma solicitação inesperada é um sinal de alerta, não a confirmação de que uma conta foi comprometida.'},
  };

  static IntelligenceEntry localize(IntelligenceEntry entry, String languageCode) {
    if (languageCode != 'pt' && languageCode != 'pt-PT') return entry;
    final values = _entries[entry.id];
    if (values == null) return entry;
    return IntelligenceEntry(id: entry.id, title: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['title']!) : values['title']!, category: entry.category,
      signal: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['signal']!) : values['signal']!, meaning: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['meaning']!) : values['meaning']!, action: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['action']!) : values['action']!, limit: languageCode == 'pt-PT' ? PortuguesePortugalText.adapt(values['limit']!) : values['limit']!);
  }
}
